def med_of_med(sect):
    # If the subset has less than 5 elements, we can just sort it
    if len(sect) < 5:
        return sorted(sect)[(len(sect) - 1) // 2]

    # Split the subset into chunks of size 5
    chunks = [sect[i:i + 5] for i in range(0, len(sect), 5)]

    md = [med_of_med(chunk) for chunk in chunks]

    # Find the median of those medians
    return med_of_med(md)

