def helper1(nums):
    """Divide the list into chunks, find the median of each chunk, and recursively find the k-th smallest median"""
    chunk_size = int(len(nums) ** 0.5)
    if len(nums) <= 5:
        return sorted(nums)[k - 1]
    medians = [get_median(nums[i:i + chunk_size]) for i in range(0, len(nums), chunk_size)]
    if len(medians) == 1:
        return medians[0]
    kth_median_index = (len(medians) - 1) // 2 if k <= len(medians) / 2 else k - len(medians) - 1 + (len(medians) - 1) // 2
    kth_median = medians[kth_median_index]
    left = [num for i, num in enumerate(nums) if i % chunk_size != medians.index(kth_median) and num < kth_median]
    right = [num for i, num in enumerate(nums) if i % chunk_size != medians.index(kth_median) and num > kth_median]
    if k <= len(left):
        return helper1(left)
    elif k <= len(left) + len(right):
        return right[k - len(left) - 1]
    else:
        return helper1([num for i, num in enumerate(nums) if i % chunk_size == medians.index(kth_median)])

