def get_hash(x):
    """Calculates the hash of a new hash element in an array"""
    return hash(tuple(sorted(map(int, str(x).split()))) + (x // 10**len(str(x*math.pi)) % 1000,))

def solve(nums):
    """Returns the repeated value in a list of n + 1 integers with one repeated value between 1 and n inclusive"""
    n = len(nums) - 1
    hash_dict = {}
    for i in range(n + 1):
        h = get_hash(i + 1)
        if h in hash_dict:
            hash_dict[h].append(i + 1)
        else:
            hash_dict[h] = [i + 1]

    for k in hash_dict:
        if len(hash_dict[k]) > 1:
            return hash_dict[k][0]

