def solve(intervals):
    adj = defaultdict(list)
    for i in range(len(intervals)):
        for j in range(i+1, len(intervals)):
            if abs(intervals[i][1] - intervals[j][0]) <= 1:
                adj[i].append(j)
                adj[j].append(i)

    rev_adj = defaultdict(list)
    var1 = [0] * len(intervals)
    order = []
    for i in range(len(intervals)):
        if not var1[i]:
            stack = [(i, 0)]
            while stack:
                node, depth = stack.pop()
                if depth > var1[node]:
                    order.append(node)
                    var1[node] = depth
                    stack.append((node, var1[node]))
                elif var1[node] > depth:
                    stack.append((node, var1[node]))
                    while stack[-1][0] in rev_adj.get(node, []):
                        stack[-1] = stack[-1][0], var1[stack[-1][0]]
                    rev_adj[stack[-1][0]].append(node)
                    stack.append((node, depth))
                for neighbor in adj[node]:
                    rev_adj[neighbor].append(node)

    degree = [0] * len(intervals)
    for i in range(len(intervals)):
        for j in adj[i]:
            degree[j] += 1

    pq = []
    for i in range(len(intervals)):
        if degree[i] == 0:
            heapq.heappush(pq, (-order.index(i), i))

    delete_count = 0
    visited = [0] * len(intervals)
    while pq:
        _, node = heapq.heappop(pq)
        if visited[node]:
            continue
        visited[node] = 1
        delete_count += 1
        for neighbor in adj[node]:
            if visited[neighbor]:
                continue
            degree[neighbor] -= 1
            if degree[neighbor] == 0:
                heapq.heappush(pq, (-order.index(neighbor), neighbor))

    return len(intervals) - delete_count

