def solve(haystack, needle):
    def helper1(s):
        p = 31
        m = 10 ** 9 + 7
        n = len(s)
        h = [0] * (n + 1)
        a = [ord(c) - ord('a') for c in s]
        h[0] = 1
        for i in range(1, n + 1):
            h[i] = (h[i - 1] * p + a[i - 1]) % m
        return h

    def length1(h, l, n):
        p = 31
        m = 10 ** 9 + 7
        d = h[l] - h[0] * (p ** (n - l))
        return d % m if d >= 0 else d + m

    def hash_same_length(h1, h2):
        return h1 == h2

    n = len(haystack)
    m = len(needle)
    if n < m:
        return -1

    h1 = helper1(needle)
    h2 = helper1(haystack[:m])

    if hash_same_length(h1[m], h2[m]):
        for i in range(m):
            if haystack[i] != needle[i]:
                return -1
        return 0

    p = 31
    m = 10 ** 9 + 7
    d = (ord(needle[0]) - ord('a')) * (p ** (m - 1))

    j = 1
    while j < n - m + 1:
        h2 = (p * h2[j - 1] + ord(haystack[j - 1]) - d * (ord(haystack[j - m]) - ord('a'))) % m
        if hash_same_length(h2, h1[m]):
            match = 0
            while haystack[j + match] == needle[match]:
                match += 1
            if match == m:
                return j
        j += 1

    return -1

