from heapq import heappop, heappush, heapreplace

def solve(n, prerequisites):
    g = defaultdict(list)
    var1 = [0] * n
    for u, v in prerequisites:
        g[v].append(u)
        var1[u] += 1

    available = [0] * n
    leak = set()

    queue = []
    for i in range(n):
        if var1[i] == 0:
            queue.append(i)
            available[i] = 1

    for i in range(n):
        while queue:
            u = heappop(queue)
            for v in g[u]:
                var1[v] -= 1
                available[v] = 2
                if var1[v] == 0:
                    heappush(queue, v)

        for i in range(n):
            if available[i] == 0:
                var1[i] -= 1
                heappush(queue, i)
            elif available[i] == 2:
                available[i] = 1

        ind = next((i for i in range(n) if available[i] == 1), None)
        if ind is not None:
            heappush(queue, ind)

        if len(queue) != n:
            leak.add(heappop(queue))

        if len(queue) != n:
            break

    order = []
    for i in range(n):
        if available[i] != 0:
            return []

        if i in leak:
            return []

        heapreplace(queue, i)

    while queue:
        order.append(heappop(queue))

    return order

