            dp.append(dp[size - 1][:])
            dp[size][i] = size

    for a, b in sorted(prerequisites, key=lambda x: x[0]):
        if dp[a] < dp[b]:
            return []
        if not dp[b]:
            add_task(b)
        for i in range(n):
