                add_task(i)
                if a == i: dp[size - 1][i] = size - 1
        if dp[a] and dp[a][b]:
            dp[a][b] = size
        elif not dp[a]:
            add_task(a)
            dp[a][b] = size
        elif dp[b] > dp[a]:
            return []

    return [i - 1 for i in sorted((j + 1 for j in map(max, dp)))]

