def mergesort(intervals, low = 0, end = None):
    if end is None:
        end = len(intervals) - 1
    if low >= end: return

    i = low
    j = low
    k = low
    pivot = intervals[(low + end) // 2]

    while i <= end:
        if intervals[i][0] < pivot[0]:
            if j < i:
                intervals[k], intervals[j] = intervals[j], intervals[k]
                k += 1
                j += 1
            else:
                k += 1
        elif intervals[i][0] == pivot[0]:
            if intervals[i][1] < pivot[1]:
                if j < i:
                    intervals[k], intervals[j] = intervals[j], intervals[k]
                    k += 1
                    j += 1
                else:
                    k += 1
            else:
                j += 1
                i += 1
        else:
            i += 1

    rebump(intervals, low, k - 1)
    rebump(intervals, k, end)
    mergesort(intervals, low, k - 1)
    mergesort(intervals, k, end)

