class IntervalNode:
    def __init__(self, start: int, end: int):
        self.start = start
        self.end = end
        self.left = None
        self.right = None

class helper1:
    def __init__(self):
        self.root = None

    def insert(self, node, start: int, end: int):
        if node is None:
            node = IntervalNode(start, end)
            return node
        if start <= node.start:
            node.left = self.insert(node.left, start, end)
        else:
            node.right = self.insert(node.right, start, end)
        return node

    def _exists(self, node, query_start: int, query_end: int, intersect_start: int, intersect_end: int):
        found_left = intersect_start <= node.end
        if found_left and query_end >= node.start:
            found_right = intersect_end >= node.start
        else:
            found_right = False
        return found_left or found_right

    def query(self, root, query_start: int, query_end: int):
        if root is None:
            return False
        intersect_start = max(query_start, root.start)
        intersect_end = min(query_end, root.end)
        return self._exists(root, query_start, query_end, intersect_start, intersect_end)

    def _remove(self, node, remove_start: int, remove_end: int):
        child = None
        if node is None:
            return None, True
        if remove_start <= node.start and remove_end >= node.end:
            return None, True
        if node.left is None and node.right is None:
            return node, False
        found_left = remove_start <= node.start and remove_end >= node.start
        if found_left:
            if remove_end >= node.end:
                child = node.right
            else:
                child = node.left
        found_right = remove_start <= node.end and remove_end >= node.end
        if child is not None and (found_left or found_right):
            return node, False
        node.left = self._remove(node.left, remove_start, remove_end)
        if node.left is not None and node.right is not None and node.left.start >= node.right.start:
            node = self._rotate_right(node)
        node.right = self._remove(node.right, remove_start, remove_end)
        if node.left is not None and node.right is not None and node.left.start >= node.right.start:
            node = self._rotate_right(node)
        return node, found_left or found_right

    @staticmethod
    def _rotate_right(node):
        p = node.left
        node.left = p.right
        p.right = node
        return p

def solve(intervals: List[List[int]]) -> List[List[int]]:
    intervals.sort(key=lambda x: x[0])
