    def __init__(self):
        self.groups = {}

    def find(self, x):
        try:
            root = x
            while self.groups[root] != root:
                root = self.groups[root]
            while x != root:
                x, self.groups[x] = self.groups[x], root
            return root
        except KeyError:
            self.groups[x] = x
            return x

    def merge(self, x, end):
        root_x = self.find(x)
        for t in self.groups:
            if self.groups[t] == root_x and (t < end or (x < end and x != t)):
                end = max(end, t)

        for y in range(x, end + 1):
            self.groups[self.find(y)] = root_x

