    from functools import lru_cache

    @lru_cache(None)
    def helper2(self, nums):
        if len(nums) <= 1:
            return nums
        mid = len(nums) // 2
        return merge(self.merge_sort(nums[:mid]), self.merge_sort(nums[mid:]))

    def merge(self, a, b):
        res = []
        i = j = 0
        while i < len(a) and j < len(b):
            if a[i] <= b[j]:
                res.append(a[i])
                i += 1
            else:
                res.append(b[j])
                j += 1
        res.extend(a[i:])
        res.extend(b[j:])
        return res

