    def propagatedRoute(edges: List[List[int]], labels: List[int]) -> bool:
        changes = False
        for u in range(n):
            min_label = labels[u]
            for v in edges[u]:
                min_label = min(min_label, labels[v])
            if labels[u] != min_label:
                labels[u] = min_label
                changes = True
        return changes

