class AVLTree:
    def __init__(self):
        self.root = None

    def insert(self, start, end):
        node = self._insert(self.root, start, end)
        self.root = self._balance(node)

    def _insert(self, node, start, end):
        if not node:
            return Node(start, end)
        if start < node.start:
            node.children['left'] = self._insert(node.children['left'], start, end)
        else:
            node.children['right'] = self._insert(node.children['right'], start, end)
        if not node.children['left'] and not node.children['right']:
            node.max_end = max(node.max_end, end)
        elif node.children['left']:
            node.max_end = max(node.max_end, self.get_max_end(node.children['left']))
        elif node.children['right']:
            node.max_end = max(node.max_end, self.get_max_end(node.children['right']))
        return node

    def get_max_end(self, node):
        if not node:
            return -1
        if not node.children['left'] and not node.children['right']:
            return node.max_end
        return max(self.get_max_end(node.children['left']), self.get_max_end(node.children['right']))

    def _balance(self, node):
        balance = self.get_balance(node)
        if balance > 1:
            if self.get_balance(node.children['left']) >= 0:
                return self._rotate_right(node)
            else:
                node.children['left'] = self._rotate_left(node.children['left'])
                return self._rotate_right(node)
        if balance < -1:
            if self.get_balance(node.children['right']) <= 0:
                return self._rotate_left(node)
            else:
                node.children['right'] = self._rotate_right(node.children['right'])
                return self._rotate_left(node)
        return node

    def get_balance(self, node):
        if not node:
            return 0
        return self.getHeight(node.children['left']) - self.getHeight(node.children['right'])

    def getHeight(self, node):
        if not node:
            return 0
        return 1 + max(self.getHeight(node.children['left']), self.getHeight(node.children['right']))

    def _rotate_left(self, node):
        temp = node.children['right']
        node.children['right'] = temp.children['left']
        temp.children['left'] = node
        return temp

    def _rotate_right(self, node):
        temp = node.children['left']
        node.children['left'] = temp.children['right']
        temp.children['right'] = node
        return temp

