def solve(n, edges):
    labels = list(range(n))
    modified = True

    def is_modified(labels):
        return any(i != min(j for j in range(n) if labels[j] < i) for i in range(n))

    while modified:
        modified = False

        to_update = [-1] * n
        for u, v in edges:
            to_update[labels[u]] = min(to_update[labels[u]], labels[v])
            to_update[labels[v]] = min(to_update[labels[v]], labels[u])

        for i in range(n):
            if labels[i] != min(to_update[i], labels[i]):
                to_update[i] = labels[i]
                labels[i] = min(to_update[i], labels[i])
                modified = True

    # Count connected components
    return sum(1 for i in labels if any(labels[j] == labels[i] for j in range(n) if i != j))

