class helper1:

    def __init__(self, n):
        self.n = n
        self.treap = [None] * (2 * n)

    def _lca(self, k):
        """Find the k-th smallest rank in the right child subtree"""
        pa = 0
        pc = self.n
        while pc - pa > 1:
            md = (pc + pa) // 2
            if sum(self.treap[md + self.n]) >= k:
                pc = md
            else:
                pa = md
        return pc

    def _lca_rank(self, k):
        """Query the rank (1-indexed) of the k-th smallest value in the right child subtree"""
        rank = 0
        pa = 0
        pc = self.n
        while pc - pa > 1:
            md = (pc + pa) // 2
            if sum(self.treap[md + self.n]) >= k:
                rank += md + 1
                pa = md
            else:
                pc = md
        return rank

    def range_max(self, l, r):
        """Compute the maximum value in the interval [l, r)"""
        if r <= l:
            return -10000
        tot = None
        for sake in (l, r):
            low = 0
            high = self.n - 1
            while low < high:
                mid = (low + high) // 2
                v = self._lca(mid + 1)
                if v >= sake:
                    high = mid
                else:
                    low = mid + 1
            rank = self._lca_rank(sake)
            tot = max(tot, self.treap[rank + self.n][rank])
        return tot

    def update_range_max(self, l, r, y):
        """Update the maximum value in the interval [l, r)"""
        for sake in (l, r):
            low = 0
            high = self.n - 1
            while low < high:
                mid = (low + high) // 2
                v = self._lca(mid + 1)
                if v >= sake:
                    high = mid
                else:
                    low = mid + 1
            idx = self._lca_rank(sake)
            ych = (y,) + self.treap[idx + self.n]
            self.treap[idx + self.n] = max(ych, ych[1:])


