    def __init__(self):
        self.var1 = []

    def push(self, val):
        self.var1.append(val)
        self._bubble_up(len(self.var1) - 1)

    def pop(self):
        if len(self.var1) == 0:
            raise ValueError("Heap is empty")
        if len(self.var1) == 1:
            return self.var1.pop()
        root = self.var1[0]
        self.var1[0] = self.var1.pop()
        self._bubble_down(0)
        return root

    def _bubble_up(self, i):
        while i > 0:
            parent = (i - 1) // 2
            if self.var1[parent] <= self.var1[i]:
                break
            self.var1[parent], self.var1[i] = self.var1[i], self.var1[parent]
            i = parent

    def _bubble_down(self, i):
        while True:
            left = 2 * i + 1
            right = 2 * i + 2
            smallest = i
            if left < len(self.var1) and self.var1[left] < self.var1[smallest]:
                smallest = left
            if right < len(self.var1) and self.var1[right] < self.var1[smallest]:
                smallest = right
            if smallest == i:
                break
            self.var1[i], self.var1[smallest] = self.var1[smallest], self.var1[i]
            i = smallest

