        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]

    def union_set(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            if rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            elif rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            else:
                parent[root_j] = root_i
                rank[root_i] += 1

    graph = defaultdict(list)
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            if intervals[i][1] <= intervals[j][0]:
                graph[i].append(j)
                graph[j].append(i)
            union_set(i, j + len(intervals))

    in_same_set = defaultdict(set)
    for i in range(len(intervals)):
        root = find(i)
        if i >= len(intervals):
            in_same_set[root].add(i - len(intervals))
        else:
            in_same_set[root].add(i)

    max_path = 0
    seen = set()
    for i in range(len(intervals)):
        stack = [(i, len(graph[i]))]
        max_path_included = 0
        while stack:
            node, step = stack.pop()
            if node not in seen:
                seen.add(node)
                max_path_included += 1
                max_path = max(max_path, max_path_included)
                for neighbor in in_same_set[find(node)]:
                    stack.append((neighbor, graph[neighbor].count(neighbor)))
                stack.append((node, max(0, step - 1)))

    return len(intervals) - max_path

