def split(current):
    if current is None:
        return current, None, None
    left, right = current.left, current.right
    current.left, current.right = None, None

    lower = None
    higher = left
    while True:
        lower_half = higher.left
        higher_half = higher.right
        if lower_half is None:
            lower = higher
            right = higher_half
            break
        elif higher_half is None:
            lower = higher
            right = higher_half
            break
        elif lower_half.start <= higher_half.end:
            higher = higher_half
        else:
            break
    return lower, higher, right

