    def find_kth_freq(counts, k):
        target = counts[k - 1] if type(counts) == list else k - 1
        lo = 0
        hi = len(counts) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if counts[mid] > target: hi = mid
            else: lo = mid + 1
