            if count >= freq:
                yield num

    return list(query(count_map, kth_freq))

def find_k(data, func, k):
    def __helper(lo, hi):
        if hi - lo <= 1:
            if func(data[lo]) >= func(data[hi]):
                return lo
            else:
                return hi
        mid = (lo + hi) // 2
        pivot_index = __helper(lo, mid)
        if pivot_index == len(data) or func(data[pivot_index]) != func(data[mid]):
            return __helper(lo, mid)
        else:
            return __helper(mid, hi)
    return find_kth(data, k, func, __helper)

def find_kth(data, k, func, find_k):
    def __helper(lo, hi):
        if lo == hi: 
            return data[lo]
        pivot_index = find_k(lo, hi)
        if k <= func(data[pivot_index]):
            return __helper(lo, pivot_index)
        else:
            return __helper(pivot_index + 1, hi)
    return __helper(0, len(data) - 1)

